package vibe.leaks_world;

import java.util.Random;

import dev.vibecraft.api.ModuleContext;
import dev.vibecraft.api.VibeModule;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.WorldCreator;
import org.bukkit.generator.ChunkGenerator;
import org.bukkit.generator.WorldInfo;

/**
 * REDTEAM-LEAKS: "create a sky/void world for a minigame" with a module ChunkGenerator. The world outlives the
 * generation; new chunks are generated by the server (worker threads) with the OLD generator.
 * /lkworld create   creates world leaks_void (if absent)
 */
public class LeaksWorldModule implements VibeModule {

    static final class VoidGen extends ChunkGenerator {
        final int gen;

        VoidGen(int gen) {
            this.gen = gen;
        }

        @Override
        public void generateNoise(WorldInfo info, Random random, int chunkX, int chunkZ, ChunkData data) {
            if (chunkX == 0 && chunkZ == 0) {
                data.setBlock(0, 64, 0, Material.GOLD_BLOCK);
            }
        }
    }

    @Override
    public void enable(ModuleContext ctx) {
        int g = ctx.generation();
        ctx.command("lkworld", (sender, args) -> {
            World w = Bukkit.getWorld("leaks_void");
            if (w == null) {
                w = new WorldCreator("leaks_void").generator(new VoidGen(g)).createWorld();
                sender.sendMessage("created leaks_void with generator v" + g);
            } else {
                sender.sendMessage("leaks_void exists, generator=" + w.getGenerator());
            }
        });
    }
}
